        let message = analysis
            .degradation
            .map_or_else(|| "parse errors; blocks may be incomplete".to_owned(), |reason| reason.to_string());
        diagnostics.push(Diagnostic { kind: DiagnosticKind::Degraded, path: Some(path.to_owned()), message });
    }
