    let mut owned: Vec<Vec<usize>> = vec![Vec::new(); blocks.len()];
    let mut credited = vec![false; hits.len()];

    let starts = hits.iter().zip(line_starts).enumerate().filter_map(|(index, (hit, line_start))| {
        let line_start = (*line_start)?;
