marker="/// What the walk produced, in the order it produced it.\nenum WalkItem {"
new='''/// What a walk found and where it belongs in the walk order.
enum Found {
    File(Utf8PathBuf),
    /// A failure, placed at `at`: the entry it was reported with, or the path it names. `rank` orders failures that share
    /// a place: those an entry carries come before one that stopped the walk below it.
    Failure { at: Utf8PathBuf, rank: u8, error: WalkError },
}

const CARRIED_BY_ENTRY: u8 = 0;
const STOPPED_THE_WALK: u8 = 2;

impl Found {
    /// Where this sits in the order a walk visiting each directory's entries by file name would produce: the path,
    /// compared component by component, then the rank. A directory's own failures sort before what is below it.
    fn place(&self) -> (&Utf8Path, u8) {
        match self {
            Self::File(path) => (path, 1),
            Self::Failure { at, rank, .. } => (at, *rank),
        }
    }
}

/// What one walk thread collected.
#[derive(Default)]
struct WalkPart {
    found: Vec<Found>,
    non_utf8_paths: u64,
    /// The failure to list the root itself, which fails the search.
    root_error: Option<ignore::Error>,
}

/// What the walk produced, in walk order.
struct Walked {
    items: Vec<WalkItem>,
    non_utf8_paths: u64,
}

/// Walks `builder`'s root on as many threads as the `ignore` crate chooses and returns the files `wanted` accepts and
/// the failures, in the order a walk that visits each directory's entries in byte order of their file names would
/// produce them, so the result never depends on which thread reached an entry first.
///
/// Each thread keeps what it finds and the parts are merged and sorted by path after the walk ends. Work is bounded by
/// the files the walk offers, and only the accepted paths are kept.
fn walk_files(
    builder: &WalkBuilder,
    root: &Utf8Path,
    wanted: &(dyn Fn(&Utf8Path) -> bool + Sync),
    allow_tests: bool,
) -> Result<Walked> {
    let parts = Mutex::new(Vec::new());
    builder.build_parallel().visit(&mut PartBuilder { root, wanted, allow_tests, parts: &parts });
    let mut walked = Walked { items: Vec::new(), non_utf8_paths: 0 };
    let mut found = Vec::new();
    for part in parts.into_inner().unwrap_or_else(std::sync::PoisonError::into_inner) {
        if let Some(source) = part.root_error {
            return Err(MonoklError::Walk { path: root.to_owned(), source });
        }
        walked.non_utf8_paths += part.non_utf8_paths;
        found.extend(part.found);
    }
    found.sort_by(|a, b| a.place().cmp(&b.place()));
    walked.items = found
        .into_iter()
        .map(|found| match found {
            Found::File(path) => WalkItem::File(path),
            Found::Failure { error, .. } => WalkItem::WalkError(error),
        })
        .collect();
    Ok(walked)
}

struct PartBuilder<'a> {
    root: &'a Utf8Path,
    wanted: &'a (dyn Fn(&Utf8Path) -> bool + Sync),
    allow_tests: bool,
    parts: &'a Mutex<Vec<WalkPart>>,
}

impl<'a> ParallelVisitorBuilder<'a> for PartBuilder<'a> {
    fn build(&mut self) -> Box<dyn ParallelVisitor + 'a> {
        Box::new(PartVisitor {
            root: self.root,
            wanted: self.wanted,
            allow_tests: self.allow_tests,
            part: WalkPart::default(),
            parts: self.parts,
        })
    }
}

/// One walk thread's visitor. It hands what it found to the shared list when the walk is over.
struct PartVisitor<'a> {
    root: &'a Utf8Path,
    wanted: &'a (dyn Fn(&Utf8Path) -> bool + Sync),
    allow_tests: bool,
    part: WalkPart,
    parts: &'a Mutex<Vec<WalkPart>>,
