import os, re, subprocess, sys
# usage: phase.py runs cwd binary args... ; min over runs of each "PROF label value" line, in ms
runs = int(sys.argv[1]); cwd = sys.argv[2]; argv = sys.argv[3:]
best = {}
for _ in range(runs):
    err = subprocess.run(argv, cwd=cwd, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE, text=True).stderr
    for line in err.splitlines():
        m = re.match(r"PROF (.+?) ([\d.]+)(ms|µs|s)\b", line)
        if m:
            v = float(m.group(2)) * {"ms": 1, "µs": 0.001, "s": 1000}[m.group(3)]
            best[m.group(1)] = min(best.get(m.group(1), 1e9), v)
print(" ".join(f"{k}={v:.1f}" for k, v in best.items()), f"load {os.getloadavg()[0]:.0f}")

