/// Where this sits in the order a walk that visits each directory's entries by file name produces: the path,
/// compared component by component, then the rank. A directory's own failures sort before what is below it.
///
/// Comparing whole paths as bytes would put `a.b` before `a/x`, because `.` is below `/`; a walk visits `a` and all
/// below it first. Writing each separator as a zero byte, which no file name holds, makes a byte comparison agree
/// with the walk, and is far cheaper than comparing components.
fn sort_key(&self) -> (Vec<u8>, u8) {
    let (path, rank) = match self {
        Self::File(path) => (path, 1),
        Self::Failure { at, rank, .. } => (at, *rank),
    };
    (path.as_str().bytes().map(|byte| if byte == b'/' { 0 } else { byte }).collect(), rank)
}

